// Risk monitoring logic
const portfolio = $('Get Portfolio').first().json;
const status = $('Get Status').first().json;

const equity = portfolio.portfolio?.equity || 0;
const totalValue = portfolio.portfolio?.total_value_usd || 0;
const tradesRemaining = status.today?.trades_remaining || 10;
const tradingHalted = status.trading_halted || false;

// Risk thresholds
const INITIAL_CAPITAL = 50;
const KILL_SWITCH_PCT = 5;
const WARNING_PCT = 3;

const drawdownPct = ((INITIAL_CAPITAL - equity) / INITIAL_CAPITAL) * 100;
const isKillSwitch = drawdownPct >= KILL_SWITCH_PCT;
const isWarning = drawdownPct >= WARNING_PCT;

let action = 'normal';
let alertLevel = 'info';
let message = '';

if (tradingHalted) {
  action = 'halted';
  alertLevel = 'critical';
  message = `Trading already halted: ${status.halt_reason}`;
} else if (isKillSwitch) {
  action = 'kill_switch';
  alertLevel = 'critical';
  message = `KILL SWITCH: ${drawdownPct.toFixed(1)}% drawdown exceeds ${KILL_SWITCH_PCT}% limit`;
} else if (isWarning) {
  action = 'warning';
  alertLevel = 'warning';
  message = `WARNING: ${drawdownPct.toFixed(1)}% drawdown approaching limit`;
} else {
  message = `Normal: Equity $${equity.toFixed(2)}, ${drawdownPct > 0 ? drawdownPct.toFixed(1) + '% down' : 'no drawdown'}`;
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    action,
    alert_level: alertLevel,
    message,
    metrics: {
      equity,
      total_value_usd: totalValue,
      initial_capital: INITIAL_CAPITAL,
      drawdown_pct: drawdownPct,
      trades_remaining: tradesRemaining,
      trading_halted: tradingHalted
    },
    thresholds: {
      kill_switch_pct: KILL_SWITCH_PCT,
      warning_pct: WARNING_PCT
    }
  }
}];

const risk = $('Risk Analysis').first().json;
console.log('=== KILL SWITCH ACTIVATED ===');
console.log('Drawdown:', risk.metrics.drawdown_pct.toFixed(1) + '%');
console.log('Equity:', '$' + risk.metrics.equity.toFixed(2));
console.log('Action: Trading halted');
return [{ json: { alert_type: 'kill_switch', ...risk, trading_halted: true } }];

const risk = $('Risk Analysis').first().json;
if (risk.alert_level === 'warning') {
  console.log('=== RISK WARNING ===');
  console.log(risk.message);
} else {
  console.log('=== RISK CHECK: OK ===');
  console.log('Equity: $' + risk.metrics.equity.toFixed(2));
}
return [{ json: { logged: true, ...risk } }];
